import{_ as r,o as t,c as i,ah as n}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Gerichtliche Nachspiele: Thomas Schmid (Der Archivar der Macht)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/gericht-thomas-schmid.md","filePath":"recherche/gericht-thomas-schmid.md"}'),a={name:"recherche/gericht-thomas-schmid.md"};function s(h,e,d,o,l,m){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="gerichtliche-nachspiele-thomas-schmid-der-archivar-der-macht" tabindex="-1">Gerichtliche Nachspiele: Thomas Schmid (Der Archivar der Macht) <a class="header-anchor" href="#gerichtliche-nachspiele-thomas-schmid-der-archivar-der-macht" aria-label="Permalink to &quot;Gerichtliche Nachspiele: Thomas Schmid (Der Archivar der Macht)&quot;">​</a></h1><p><strong>Vom treuen Vertrauten zum wichtigsten Kronzeugen der Zweiten Republik.</strong></p><p>Thomas Schmid war der Mann im Zentrum des „Systems Kurz“. Als Generalsekretär im Finanzministerium und späterer ÖBAG-Chef verwaltete er nicht nur das Staatsvermögen, sondern auch die informellen Netzwerke der Macht. Seine sichergestellten Chats sind die „Rosetta-Steine“ der modernen österreichischen Korruptionsforschung.</p><hr><h2 id="die-rolle-im-system" tabindex="-1">Die Rolle im System <a class="header-anchor" href="#die-rolle-im-system" aria-label="Permalink to &quot;Die Rolle im System&quot;">​</a></h2><h3 id="_1-das-digitale-gedachtnis" tabindex="-1">1. Das digitale Gedächtnis <a class="header-anchor" href="#_1-das-digitale-gedachtnis" aria-label="Permalink to &quot;1. Das digitale Gedächtnis&quot;">​</a></h3><p>Die Sicherstellung seines Mobiltelefons (im Zuge der Ibiza-Ermittlungen) brachte über 300.000 Chat-Nachrichten ans Licht. Diese dokumentieren detailliert:</p><ul><li><strong>Postenschacher:</strong> „Kriegst eh alles, was du willst.“</li><li><strong>Umfragen-Manipulation:</strong> Das Beinschab-Österreich-Tool.</li><li><strong>Steuer-Interventionen:</strong> Wie Großinvestoren (wie René Benko) bevorzugt behandelt wurden.</li></ul><h3 id="_2-der-kronzeugenstatus-oktober-2022" tabindex="-1">2. Der Kronzeugenstatus (Oktober 2022) <a class="header-anchor" href="#_2-der-kronzeugenstatus-oktober-2022" aria-label="Permalink to &quot;2. Der Kronzeugenstatus (Oktober 2022)&quot;">​</a></h3><p>Nach monatelangen Befragungen durch die WKStA legte Thomas Schmid ein umfassendes Geständnis ab. Er belastete zahlreiche Spitzenpolitiker der ÖVP (darunter Sebastian Kurz und Wolfgang Sobotka) und strebt seither den offiziellen Kronzeugenstatus an.</p><hr><h2 id="die-verbindung-zum-horten-mysterium" tabindex="-1">Die Verbindung zum Horten-Mysterium <a class="header-anchor" href="#die-verbindung-zum-horten-mysterium" aria-label="Permalink to &quot;Die Verbindung zum Horten-Mysterium&quot;">​</a></h2><p>Thomas Schmid ist die akustische Brücke in unserem Projekt:</p><ul><li><strong>Die Benko-Achse:</strong> Schmid war die Anlaufstelle für René Benko im Finanzministerium, wenn es um steuerliche Erleichterungen oder COFAG-Hilfen ging.</li><li><strong>Die Horten-Spenden:</strong> Seine Chats liefern den Kontext zur „Ästhetik der Stückelung“. Er wusste, wie man Spenden so platziert, dass sie das System am Laufen halten, ohne Alarm auszulösen.</li></ul><hr><h2 id="status-marz-2026-der-showdown-in-linz" tabindex="-1">Status März 2026: Der Showdown in Linz <a class="header-anchor" href="#status-marz-2026-der-showdown-in-linz" aria-label="Permalink to &quot;Status März 2026: Der Showdown in Linz&quot;">​</a></h2><p>Thomas Schmid steht vor seinem bisher brisantesten Auftritt als Kronzeuge im Prozess gegen August Wöginger am Landesgericht Linz.</p><h3 id="_1-termin-9-marz-2026" tabindex="-1">1. Termin: 9. März 2026 <a class="header-anchor" href="#_1-termin-9-marz-2026" aria-label="Permalink to &quot;1. Termin: 9. März 2026&quot;">​</a></h3><p>Am kommenden Montag wird Schmid persönlich in Linz aussagen. Er ist der zentrale Zeuge der WKStA, da er Wöginger als „Bestimmungstäter“ direkt belastet. Er behauptet, Wöginger habe ihn zur Intervention beim Finanzamt Braunau angestiftet.</p><h3 id="_2-die-strategie-der-verteidigung-stand-3-marz-2026" tabindex="-1">2. Die Strategie der Verteidigung (Stand 3. März 2026) <a class="header-anchor" href="#_2-die-strategie-der-verteidigung-stand-3-marz-2026" aria-label="Permalink to &quot;2. Die Strategie der Verteidigung (Stand 3. März 2026)&quot;">​</a></h3><p>Bereits am ersten Tag der Wöginger-Einvernahme haben die Mitangeklagten (insb. der Gewerkschafter Herbert B.) Schmid frontal angegriffen. Seine belastenden Aussagen wurden im Gerichtssaal als <strong>„Lüge“</strong> bezeichnet.</p><ul><li><strong>Das Ziel:</strong> Schmid soll vor seinem Auftritt als unglaubwürdig diskreditiert werden, um seinen Kronzeugenstatus zu gefährden.</li><li><strong>Mockumentary-Kontext:</strong> In Szene 13 („Der Dirigent der Verfahren“) nutzen wir diese Dynamik. Wir stellen Schmid als einen Tenor dar, dessen Arie die Harmonie der Macht stört und den man deshalb „mundtot“ reimen will.</li></ul><hr><p><em>Quellen: Aktuelle Prozessberichterstattung (03.03.2026), Einvernahmeprotokolle der WKStA (2022-2024).</em></p>',24)])])}const g=r(a,[["render",s]]);export{c as __pageData,g as default};
